        [8712] = {
            description = "The Qiraji and their servants wield items made with the rarest and finest " ..
                "materials: bones from gargantuan ancient creatures, gems from the depths of the earth, " ..
                "metals pure and strong.\n\nJust the sight of Qiraji artifacts fills me with an urge to " ..
                "practice my craft with their shattered and smelted pieces. Prove your allegiance to the " ..
                "Circle, <name>, and I will make you a powerful weapon from the finest Qiraji materials.",
            rewardItems = {{21401, 1}},
        },
        [8728] = {
            description = "Well that took a little longer than expected. Now let me see what this ledger " ..
                "says.\n\n<Narain silently reads the ledger, periodically mumbling under his " ..
                "breath.>\n\nThe good news is that I am 99% certain that I am capable of creating an " ..
                "arcanite buoy that will function to your specifications. This is, of course, wholly " ..
                "dependant on the bad news.\n\nThe bad news is that I'm going to need a lot of arcanite, " ..
                "elementium ore, and rare gemstones.\n\nBring me what I need and I will craft the buoy.",
        },
        [8729] = {
            description = "Did I mention the bad news yet? Its name is Maws: 100 feet of death and " ..
                "destruction. I guess I may have forgotten that little tidbit.\n\nAccording to my " ..
                "superior psycho-psionic clairvoyance, you'll find that the best spot to cast this buoy " ..
                "is off the coast of Azshara, in the Bay of Storms.\n\nLook for a swirling maelstrom, " ..
                "most likely cluttered with wreckage.\n\nBy the by, I hope you have friends.\n\nNow if " ..
                "you somehow miraculously succeed, take the scepter shard to Anachronos.",
            rewardChoices = {{21526, 1}, {21527, 1}},
        },
        [8730] = {
            description = "Champion, is it you? A thousand years it has been since I was entrusted the " ..
                "shard and it is at my darkest hour that one should rise to relieve me of it... But what " ..
                "would tragedy be without cruelty?\n\n<Vaelastrasz coughs weakly.>\n\nNe... Nefarius now " ..
                "holds the scepter shard.\n\nTime is of the essence. Nefarius plans to destroy the shard. " ..
                "You must hurry!",
            rewardChoices = {{21530, 1}, {21529, 1}},
        },
        [8731] = {
            description = "Greetings, <name>. Before I assign you to more involved tasks in the war, " ..
                "you'll need to do your share of field duty.\n\nYou will find Captain Skullsplit's " ..
                "Orgrimmar Legion outside Hive'Regal.\n\nReport to him and come back to me with proof of " ..
                "your field service. I shall have a more advanced assignment ready for you.\n\nOh, please " ..
                "do your best to stay away from the Ironforge Brigade. Tensions are high among our " ..
                "Alliance and Horde volunteers.",
            rewardChoices = {{20808, 1}, {21266, 1}, {20809, 1}},
        },
        [8732] = {rewardItems = {{20810, 1}}},
        [8735] = {
            description = "You must travel to the four dream portals of Azeroth. From each you must draw " ..
                "a fragment of the Nightmare's corruption. The dragonkin that inhabit these areas will " ..
                "hold such fragments. Return to me when you have gathered these fragments.",
        },
        [8736] = {
            description = "We must use restraint against Eranikus. We are to redeem him not destroy " ..
                "him.\n\nTyrande is already en route to assist us in this task. We must weather the " ..
                "dragon's blows and save Nighthaven from certain destruction.\n\nBe on guard! You and " ..
                "your allies are our only hope.",
            rewardChoices = {{21531, 1}, {21532, 1}},
        },
        [8737] = {
            description = "The Twilight's Hammer and the elemental nobles they worship present a " ..
                "formidable threat to our operations in Silithus. With the new enemies we're facing " ..
                "inside Ahn'Qiraj, we cannot afford to lower our guard to our enemies outside.\n\nFind a " ..
                "way to summon and destroy an Azure Templar and report to Bor Wildmane.",
            rewardItems = {{20801, 1}, {21133, 1}},
        },
        [8740] = {
            description = "Bands of mounted Twilight's Hammer cultists have been spotted riding outside " ..
                "the reach of our forces in Cenarion Hold, picking off our smaller patrols and " ..
                "caravans.\n\nFind and defeat the twilight marauders along with their leader, a terrible " ..
                "warrior by the name of Morna. Report to Windcaller Proudhorn after completing the task.",
            rewardItems = {{20801, 1}, {21133, 1}},
        },
        [8741] = {
            description = "The keeper awaits your return, <name>. Take the green scepter shard to " ..
                "Anachronos at the Caverns of Time.",
        },
        [8745] = {rewardChoices = {{21523, 1}, {21522, 1}, {21521, 1}, {21520, 1}}},
        [8747] = {rewardItems = {{21196, 1}}},
        [8748] = {rewardItems = {{21197, 1}}},
        [8749] = {rewardItems = {{21198, 1}}},
        [8750] = {rewardItems = {{21199, 1}}},
        [8751] = {rewardItems = {{21200, 1}}},
        [8752] = {rewardItems = {{21201, 1}}},
        [8753] = {rewardItems = {{21202, 1}}},
        [8754] = {rewardItems = {{21203, 1}}},
        [8755] = {rewardItems = {{21204, 1}}},
        [8756] = {rewardItems = {{21205, 1}}},
        [8757] = {rewardItems = {{21206, 1}}},
        [8758] = {rewardItems = {{21207, 1}}},
        [8759] = {rewardItems = {{21208, 1}}},
        [8760] = {rewardItems = {{21209, 1}}},
        [8761] = {rewardItems = {{21210, 1}}},
        [8764] = {rewardChoices = {{21210, 1}, {21205, 1}}},
        [8765] = {rewardChoices = {{21200, 1}, {21205, 1}}},
        [8766] = {rewardChoices = {{21200, 1}, {21210, 1}}},
        [8770] = {
            description = "As the war effort mounts, the silithid presence in the area presents an ever " ..
                "increasing threat to our operations. You've been selected to partake on an assault on " ..
                "Hive'Ashi where your primary target will consist of Hive'Ashi defenders.\n\nReport back " ..
                "to Commander Mar'alith after your task is completed.",
            rewardItems = {{20802, 1}},
        },
        [8772] = {
            description = "Reinforcements have been called on to join the assault on Hive'Zora. You have " ..
                "been selected to target Hive'Zora waywatchers. Report back to Commander Mar'alith after " ..
                "completing your task.",
            rewardItems = {{20802, 1}},
        },
        [8774] = {
            description = "As the war effort mounts, the silithid presence in the area presents an ever " ..
                "increasing threat to our operations. You've been selected to partake on an assault on " ..
                "Hive'Regal where your primary target will consist of the Hive'Regal ambushers.\n\nReport " ..
                "back to Commander Mar'alith after your task is completed.",
            rewardItems = {{20802, 1}},
        },
        [8777] = {
            description = "As the war effort mounts, the silithid presence in the area presents an ever " ..
                "increasing threat to our operations. You've been selected to partake on an assault on " ..
                "Hive'Regal where your primary target will consist of Hive'Regal burrowers.\n\nReport " ..
                "back to Commander Mar'alith after your task is completed.",
            rewardItems = {{20802, 1}},
        },
        [8778] = {
            description = "The Ironforge Brigade has put in an unusual request for highly... volatile... " ..
                "components. Gather them and bring them to Mr. Nozzlespring from the Ironforge Brigade.",
            rewardItems = {{20800, 1}, {20805, 1}},
        },
        [8779] = {
            description = "Geologist Larksbane 's studies have proven to be of tremendous value to our " ..
                "operations in Silithus. She has recently requested scrying materials to be used in her " ..
                "research.\n\nPlease gather these materials and deliver them to her directly so that she " ..
                "may continue her research.",
            rewardItems = {{20800, 1}, {20805, 1}},
        },
        [8780] = {
            description = "The Ironforge Brigade's supply of armor kits in the battlefield is running " ..
                "dangerously low. Obtain a batch and deliver them to Janela Stouthammer at the Ironforge " ..
                "Brigade's outpost outside Hive'Zora.",
            rewardItems = {{20800, 1}, {20805, 1}},
        },
        [8781] = {
            description = "The Ironforge Brigade has been a worthy ally in our fight in Silithus. " ..
                "Unfortunately, many of their supplies were lost on their way here. Procure a batch of " ..
                "weapons and deliver them to Janela Stouthammer near Hive'Zora.",
            rewardItems = {{20800, 1}, {20805, 1}},
        },
        [8782] = {
            description = "The latest influx of volunteers has caused a shortage of uniforms. Procure a " ..
                "batch of uniform materials and bring them to Windcaller Proudhorn.",
            rewardItems = {{20800, 1}, {21132, 1}},
        },
        [8784] = {
            description = "You have discovered an ancient Qiraji artifact! Perhaps one of the dragons " ..
                "near the entrance of the temple would have a use for this relic.",
        },
        [8786] = {
            description = "The Orgrimmar Legion has put in a request for additional weapons that we " ..
                "haven't been able to provide at the moment. Obtain the weapons they've requested and " ..
                "bring them to Merok Longstride outside of Hive'Regal.",
            rewardItems = {{20800, 1}, {21386, 1}},
        },
        [8787] = {
            description = "The brave volunteers of the Orgrimmar Legion have arrived to Silithus to aid " ..
                "us in our cause. Their supplies of armor kits were somehow lost in the trip. Obtain a " ..
                "batch of armor kits and deliver them to Merok Longstride at the location of the " ..
                "Orgrimmar Legion camp.",
            rewardItems = {{20800, 1}, {21386, 1}},
        },
        [8790] = {
            description = "Arygos theorizes that the element which is born of conflicts between the Old " ..
                "Gods and their minions is also extremely deadly to them under the right conditions. I " ..
                "speak of Elementium, mortal.\n\nFind and bring me Imperial Qiraji Regalia and the toxic " ..
                "element and I shall infuse weapons of great power.",
            rewardChoices = {{21273, 1}, {21275, 1}, {21268, 1}},
        },
        [8791] = {
            description = "A terrible menace has been laid to rest. The cruel Ossirian has been " ..
                "vanquished.\n\nThe denizens of Kalimdor would be relieved to know of this victory. Take " ..
                "Ossirian's head and present it to Commander Mar'alith of Cenarion Hold.",
            rewardChoices = {{21504, 1}, {21507, 1}, {21505, 1}, {21506, 1}},
        },
        [8800] = {
            description = "As you complete the tasks you're assigned in the war you'll want to talk to " ..
                "Vargus, the blacksmith. Show him any badges you've earned along the way. He'll provide " ..
                "you with gear to match your level of commitment to our cause.",
        },
        [8801] = {
            description = "The walls of Ahn'Qiraj tremble. A force of evil, older than the world itself, " ..
                "has been destroyed.\n\nAs you look at the remnants of the colossal abomination your " ..
                "heart nearly freezes. Even in death you can feel the legacy of C'Thun's evil around " ..
                "you.\n\nYou have done what was thought to be impossible.\n\nYou grab at an eye stalk of " ..
                "the fiend, stowing it safely in your pack.\n\nTake the Eye of C'Thun to the dragons in " ..
                "the next chamber.",
        },
        [8802] = {
            description = "To the Caverns of Time you go, <Lord/Lady> <name>. Anachronos awaits your " ..
                "return. Give him the eye of C'Thun as he will undoubtedly wish to place it in his " ..
                "master's collection.",
            rewardChoices = {{21712, 1}, {21710, 1}, {21709, 1}},
        },
        [8807] = {
            description = "Geologist Larksbane 's studies have proven to be of tremendous value to our " ..
                "operations in Silithus. She has recently requested scrying materials to be used in her " ..
                "research.\n\nPlease gather these materials and deliver them to her directly so that she " ..
                "may continue her research.",
            rewardItems = {{20800, 1}, {21386, 1}},
        },
        [8808] = {
            description = "The latest influx of volunteers has caused a shortage of uniforms. Procure a " ..
                "batch of uniform materials and bring them to Windcaller Proudhorn.",
            rewardItems = {{20800, 1}, {21266, 1}},
        },
        [8810] = {
            description = "Our supply of bandages in the battlefield is running dangerously low after the " ..
                "recent casualties we have incurred. Obtain a batch of first-aid supplies and deliver " ..
                "them to Windcaller Proudhorn in Cenarion Hold.",
            rewardItems = {{20800, 1}, {21386, 1}},
        },
        [8829] = {
            description = "The Twilight's Hammer operates through innumerable layers of secrecy and " ..
                "deceit. While their actions are carried out in our world, they are planned in a place we " ..
                "have not yet been able to reach.\n\nWe've come to believe that the stones the Twilight's " ..
                "Hammer uses to summon their superiors allow for two-way transportation. To attempt to " ..
                "use them in this manner, we must replicate - to every last detail - a twilight " ..
                "emissary's robe.\n\nGather the necessary materials and bring them to Aurel Goldleaf, " ..
                "<name>.",
            rewardItems = {{21515, 1}},
        },
        [8884] = {
            description = "Greetings, <class>. Take a look toward the shore; what do you see? That's " ..
                "right, our beach... our Tranquil Shore, has been infested with the malignancy known as " ..
                "the murloc.\n\nThis blight will not stand!\n\nI have a task for you. If you feel that " ..
                "you're up to it, I would have their heads! Let us see if we can put a dent in their " ..
                "numbers so large that, if they have any sense at all, they will return to the murky " ..
                "depths from which they sprang!",
        },
        [8885] = {
            description = "The Grimscale murlocs have not been scared off by your efforts. But, I think I " ..
                "know what will send them packing, as well as get me some personal retribution.\n\nThey " ..
                "have a murloc chieftain that calls itself Mmmrrrggglll. It wanders the Golden Strand " ..
                "south of the river inlet. The beast once slew a compatriot of mine, and now wears his " ..
                "ring in open defiance and mockery.\n\nSlay Mmmrrrggglll, and bring back my friend's " ..
                "ring. Then we shall see these monsters cowed!",
            rewardChoices = {{23398, 1}, {23395, 1}, {23397, 1}, {23396, 1}},
            rewardMoney = 600,
        },
        [8886] = {
            description = "Thank goodness for you, <class>! Those slimy Grimscale murlocs have pirated " ..
                "away my cargo! It's bad enough that the Wretched have stolen what little magical goods I " ..
                "had, but the murlocs took the rest! What has this land come to?\n\nCould you retrieve my " ..
                "cargo? I can't expect that you'd be able to get all of it back, but I'll be grateful for " ..
                "any of it at this point. It was the Grimscale murlocs in the huts, just to the west and " ..
                "south of the anchorage on the Golden Strand, I'm sure of it!",
            rewardMoney = 225,
        },
        [8887] = {
            description = "Interesting... what you have found here is a water-proofed, leather tube " ..
                "containing a number of sheets of parchment. By the markings upon them, the pages are " ..
                "clearly navigation rutters, and each bears the signature of one Captain " ..
                "Kelisendra.\n\nYou've heard of a small, defended camp just east of the nearby Sunsail " ..
                "Anchorage. Maybe the captain is there?",
            rewardMoney = 225,
        },
        [8888] = {
            description = "<class>, hear my request. For reasons that I cannot go into now, I decided to " ..
                "shut down my nearby school. A few days ago, I sent one of my pupils, Apprentice " ..
                "Loralthalis, there with this very task. I have not heard back from her since.\n\nWill " ..
                "you go to Duskwither Spire and check in on her, to make sure that she is well? You'll " ..
                "find it by heading north on the path out of Farstrider Retreat, then go to the right " ..
                "when the road branches.",
        },
        [8889] = {
            description = "As you may know, Magister Duskwither sent me back here to shut down the power " ..
                "sources that feed the Spire. There are three of them, each located in a different place " ..
                "inside.\n\nUnfortunately, I appear to be too late, and Duskwither Spire has been overrun " ..
                "with strange, magical creatures. While I haven't the expertise to accomplish this task, " ..
                "surely a <class>, such as yourself, could do so easily?",
        },
        [8890] = {
            description = "<name>, I have one last favor to ask of you. Would you please relay what's " ..
                "transpired here to Magister Duskwither, back at the Farstrider Retreat? Let him know " ..
                "that I am well, but make certain that he is aware that some of the apprentices have " ..
                "become Wretched.\n\nThank you for your help!",
            rewardItems = {{23399, 1}},
        },
        [8891] = {
            description = "You have discovered what appears to be an investigative journal left behind by " ..
                "Magister Duskwither. A brief scan of its contents reveal some shocking attempts at " ..
                "filtering corrupted magical flows, which might explain what has happened here at " ..
                "Duskwither Spire. The magister is sure to want this brought back to him.",
            rewardMoney = 350,
        },
        [8892] = {
            description = "Sunsail Anchorage has been overrun by Wretched scum. As soon as we manage to " ..
                "get reinforcements to the area we'll show those thugs who's boss, <name>.\n\nIn the " ..
                "meantime you can help by showing them a bit of discipline. Go in there and show them we " ..
                "are not to be trifled with. You will find Sunsail Anchorage just to the west of " ..
                "Fairbreeze Village.",
            rewardMoney = 175,
        },
        [8893] = {rewardItems = {{8647, 1}}},
        [8894] = {
            description = "It's horrible, I tell you! Strange things happening in the spire, the magister " ..
                "and his apprentices run off, and then the next thing that you know, the whole grounds " ..
                "are overrun with these magical beasties! And who told Wyllithen? No one, that's " ..
                "who!\n\n<class>, you've got to help me clear some of these things out... I cannot " ..
                "maintain the grounds while these 'anomalies' are running amok!",
            rewardMoney = 350,
        },
        [8905] = {
            description = "Well met, <class>. I've something that might interest you.\n\nI have in my " ..
                "possession a set of armor much like the one worn by those of your profession, but of " ..
                "much higher quality. I'd be willing to trade the bracers for ordinary ones in exchange " ..
                "for a small favor.\n\nThe blood of the frostsabers and bears that inhabit Winterspring " ..
                "has properties I'm in need of at the moment. Bring me a sizeable sample of it along with " ..
                "the bracers and a small amount of gold. You shall find the effort worth your while.",
            rewardItems = {{22108, 1}},
        },
        [8906] = {
            description = "Well met, <class>. I've something that might interest you.\n\nI have in my " ..
                "possession a set of armor much like the one worn by those of your profession, but of " ..
                "much higher quality. I'd be willing to trade the bracers for ordinary ones in exchange " ..
                "for a small favor.\n\nThe blood of the frostsabers and bears that inhabit Winterspring " ..
                "has properties I'm in need of at the moment. Bring me a sizeable sample of it along with " ..
                "the bracers and a small amount of gold. You shall find the effort worth your while.",
            rewardItems = {{22011, 1}},
        },
        [8907] = {
